INSERT INTO lesson_kanji (id,lesson_id,kanji_id,order_index) SELECT 6300024613,6000001003,k.id,1 FROM kanji k WHERE BINARY k.`character`=BINARY CONVERT(X'e680a5' USING utf8mb4) AND (COALESCE(TRIM(k.meaning_vi),'')<>'' OR COALESCE(TRIM(k.han_viet),'')<>'') AND EXISTS (SELECT 1 FROM kanji_reading r WHERE r.kanji_id=k.id) ON DUPLICATE KEY UPDATE lesson_id=VALUES(lesson_id),order_index=VALUES(order_index);
