('JK-8D8A', 'N4', '越', 105, 'VIỆT', '["HOẠT"]', 'vượt qua; băng qua', '["エツ","オツ"]', '["こ.す","-こ.す","-ご.し","こ.える","-ご.え"]', '["こ.す"]', 'LEVEL_WORDS', 12, 156, 'tẩu', NULL, 'Đôi chân chạy (走) vác theo chiếc rìu (戉) băng qua núi đèo là vượt qua (VIỆT).', NULL, 'AI_CHECKED', 1, '1c8c4c1be5fd'),
('JK-8DB3', 'N4', '足', 16, 'TÚC', '[]', 'bàn chân; đủ', '["ソク"]', '["あし","た.りる","た.る","た.す"]', '["あし","た.りる","た.す"]', 'LEVEL_WORDS', 7, 157, 'túc', NULL, 'Phía trên là đầu gối (口), phía dưới là bàn chân dừng lại (止), ghép thành cái chân và sự đầy đủ (TÚC).', NULL, 'AI_CHECKED', 1, '1c8c4c1be5fd'),
('JK-8E0F', 'N4', '踏', 211, 'ĐẠP', '[]', 'bước; giẫm', '["トウ"]', '["ふ.む","ふ.まえる"]', '["ふ.む"]', 'LEVEL_WORDS', 15, 157, 'túc', NULL, 'Đôi bàn chân (足) giẫm bước lên mặt nước (沓) bắn tung tóe là giẫm đạp (ĐẠP).', NULL, 'AI_CHECKED', 1, '1c8c4c1be5fd'),
('JK-8F29', 'N4', '輩', 181, 'BỐI', '[]', 'người cùng nhóm; lớp người', '["ハイ"]', '["-ばら","やから","やかい","ともがら"]', '["はい"]', 'LEVEL_WORDS', 15, 159, 'xa', NULL, 'Đoàn xe (車) xếp thành hai hàng (非) cùng tiến lên tượng trưng cho các thế hệ, tiền bối (BỐI).', NULL, 'AI_CHECKED', 1, '1c8c4c1be5fd'),
('JK-8F38', 'N4', '輸', 203, 'THÂU', '["THÚ"]', 'vận chuyển; gửi', '["ユ","シュ"]', '[]', '["ゆ"]', 'LEVEL_WORDS', 16, 159, 'xa', NULL, 'Dùng chiếc xe (車) chở hàng hóa tập hợp (兪) đi giao khắp các miền là vận chuyển (THÂU).', NULL, 'AI_CHECKED', 1, '1c8c4c1be5fd'),
('JK-8FBC', 'N4', '込', 77, 'NHẬP', '[]', 'đông đúc; cho vào', '[]', '["-こ.む","こ.む","こ.み","-こ.み","こ.める"]', '["こ.む","こ.み"]', 'LEVEL_WORDS', 5, 162, 'sước', NULL, 'Bước chân đi vào (入) con đường (辶) chật kín người, tạo nên cảnh đông đúc, chen chúc (NHẬP).', NULL, 'AI_CHECKED', 1, '1c8c4c1be5fd'),
('JK-8FD4', 'N4', '返', 128, 'PHẢN', '[]', 'trả lại; trả lời', '["ヘン"]', '["かえ.す","-かえ.す","かえ.る","-かえ.る"]', '["へん","かえ.す"]', 'LEVEL_WORDS', 7, 162, 'sước', NULL, 'Đi trên đường (辶) rồi lại quay ngược (反) trở về điểm xuất phát là trả lại, phản hồi (PHẢN).', NULL, 'AI_CHECKED', 1, '1c8c4c1be5fd'),
('JK-8FF7', 'N4', '迷', 227, 'MÊ', '[]', 'lạc lối; bối rối', '["メイ"]', '["まよ.う"]', '["まよ.う"]', 'LEVEL_WORDS', 9, 162, 'sước', NULL, 'Đi trên đường (辶) mà ngơ ngác nhìn bốn phía như hạt gạo (米) rơi vãi là bị lạc đường, bối rối (MÊ).', NULL, 'AI_CHECKED', 1, '1c8c4c1be5fd'),
('JK-9000', 'N4', '退', 219, 'THOÁI', '["THỐI"]', 'rút lui; rút khỏi', '["タイ"]', '["しりぞ.く","しりぞ.ける","ひ.く","の.く","の.ける","ど.く"]', '["たい"]', 'LEVEL_WORDS', 9, 162, 'sước', NULL, 'Gặp điều không tốt (艮) trên con đường (辶) thì chủ động quay gót bước lùi, rút lui (THOÁI).', NULL, 'AI_CHECKED', 1, '1c8c4c1be5fd'),
('JK-901A', 'N4', '通', 26, 'THÔNG', '[]', 'đi qua; giao thông', '["ツウ","ツ"]', '["とお.る","とお.り","-とお.り","-どお.り","とお.す","とお.し","-どお.し","かよ.う"]', '["つう","とお.る","とお.り","かよ.う"]', 'LEVEL_WORDS', 10, 162, 'sước', NULL, 'Dùng (用) đôi chân bước đi trên con đường (辶) thông suốt để đi qua lại (THÔNG).', NULL, 'AI_CHECKED', 1, '1c8c4c1be5fd'),
('JK-9023', 'N4', '連', 56, 'LIÊN', '[]', 'dẫn theo; dẫn dắt', '["レン"]', '["つら.なる","つら.ねる","つ.れる","-づ.れ"]', '["れん","つ.れる"]', 'LEVEL_WORDS', 10, 162, 'sước', NULL, 'Đoàn xe (車) nối đuôi nhau chạy dài trên con đường (辶), biểu thị sự dẫn theo, liên tiếp (LIÊN).', NULL, 'AI_CHECKED', 1, '1c8c4c1be5fd'),
