('JG-5a9d680484-F02', 'JG-5a9d680484', 'N4', 'FILL', 'FILL_TEXT', 2, '早く週末に＿＿かなあ。', NULL, NULL, NULL, NULL, NULL, 'ならない', NULL, 'Mong mau đến cuối tuần quá.', 'AI_CHECKED', 1, '1c8c4c1be5fd'),
('JG-5a9d680484-O01', 'JG-5a9d680484', 'N4', 'ORDER', 'ORDER', 1, '来てくれるかなあ / 彼、 / パーティーに', NULL, NULL, NULL, '["来てくれるかなあ","彼、","パーティーに"]', '[1,2,0]', NULL, NULL, 'Không biết anh ấy có đến bữa tiệc không nhỉ.', 'AI_CHECKED', 1, '1c8c4c1be5fd'),
