('JG-bec46a3c9a-C05', 'JG-bec46a3c9a', 'N4', 'CHECK', 'MEANING', 5, '出発は朝八時の予定です。', NULL, '["Đến 8 giờ vẫn chưa xuất phát được.","Theo dự kiến 8 giờ sáng xuất phát.","Tôi muốn xuất phát lúc 8 giờ.","Hôm qua chúng tôi xuất phát lúc 8 giờ."]', 1, NULL, NULL, NULL, NULL, 'Câu này nghĩa là: "Theo dự kiến 8 giờ sáng xuất phát."', 'AI_CHECKED', 1, '1c8c4c1be5fd'),
('JG-bec46a3c9a-C06', 'JG-bec46a3c9a', 'N4', 'CHECK', 'MEANING', 6, '来月、引っ越す予定です。', NULL, '["Tôi không muốn chuyển nhà.","Tháng sau tôi phải dọn nhà giúp bạn.","Tháng trước tôi đã chuyển nhà.","Tháng sau tôi dự định chuyển nhà."]', 3, NULL, NULL, NULL, NULL, 'Câu này nghĩa là: "Tháng sau tôi dự định chuyển nhà."', 'AI_CHECKED', 1, '1c8c4c1be5fd'),
('JG-bec46a3c9a-C07', 'JG-bec46a3c9a', 'N4', 'CHECK', 'ERROR', 7, 'Câu nào dùng sai mẫu?', NULL, '["出発は朝八時の予定です。","来月、引っ越す予定です。","テストは来週予定です。","飛行機は十時に着く予定です。"]', 2, NULL, NULL, NULL, NULL, 'Sai: danh từ cần の trước 予定: 来週の予定. Sửa: テストは来週の予定です。', 'AI_CHECKED', 1, '1c8c4c1be5fd'),
('JG-bec46a3c9a-C08', 'JG-bec46a3c9a', 'N4', 'CHECK', 'ERROR', 8, 'Câu nào dùng sai mẫu?', NULL, '["あしたは友達と会うの予定です。","会議は三時からの予定です。","旅行は来週の金曜日の予定です。","結婚式は六月の予定です。"]', 0, NULL, NULL, NULL, NULL, 'Sai: động từ nối thẳng với 予定, không thêm の. Sửa: あしたは友達と会う予定です。', 'AI_CHECKED', 1, '1c8c4c1be5fd'),
